mapper.select:
SELECT p.id, p.code, p.name, p.category_id as categoryId, p.category_name as categoryName, p.specification_id as specificationId, p.specification_name as specificationName, p.unit, p.price, p.status, p.create_time as createTime, p.update_time as updateTime, IFNULL((SELECT 1 FROM sal_yt_customer_store cs WHERE cs.product_id = p.id AND cs.specification_id = p.specification_id AND cs.is_deleted = 0 LIMIT 1), 0) as isStoreEnabled FROM pro_yt_product p WHERE p.is_deleted = 0
AND p.code LIKE CONCAT('%', #{params.productCode}, '%')
AND p.category_id = #{params.categoryId}
AND p.id = #{params.id}
ORDER BY p.create_time DESC

SELECT * FROM sal_yt_customer_store
WHERE product_id = #{productId}
AND specification_id = #{id}
AND customer_id = #{customerId}
AND is_deleted = 0
LIMIT 1

SELECT * FROM sal_yt_customer_store
WHERE customer_id = #{customerId}
AND specification_id = #{specificationId}
AND is_deleted = 0
LIMIT 1

mapper.update:
UPDATE sal_yt_customer_store
SET status = #{status}
WHERE id = #{id}
AND is_deleted = 0

